PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA busy_timeout=5000;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_migrations VALUES(1);
CREATE TABLE IF NOT EXISTS books(id TEXT PRIMARY KEY,title TEXT NOT NULL,author TEXT NOT NULL,created TEXT NOT NULL,glossary_revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS chapters(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,title TEXT NOT NULL,position INTEGER NOT NULL,revision INTEGER NOT NULL,raw TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chapter_revisions(chapter_id TEXT NOT NULL REFERENCES chapters(id) ON DELETE CASCADE,revision INTEGER NOT NULL,raw TEXT NOT NULL,created TEXT NOT NULL,PRIMARY KEY(chapter_id,revision));
CREATE TABLE IF NOT EXISTS segments(id TEXT PRIMARY KEY,chapter_id TEXT NOT NULL REFERENCES chapters(id) ON DELETE CASCADE,position INTEGER NOT NULL,paragraph INTEGER NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,text TEXT NOT NULL,speech_text TEXT NOT NULL,speech_revision INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS segments_chapter ON segments(chapter_id,position);
CREATE TABLE IF NOT EXISTS translations(segment_id TEXT PRIMARY KEY REFERENCES segments(id) ON DELETE CASCADE,text TEXT NOT NULL,revision INTEGER NOT NULL,manual INTEGER NOT NULL,model TEXT NOT NULL,context_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS translation_history(id TEXT PRIMARY KEY,chapter_id TEXT NOT NULL REFERENCES chapters(id) ON DELETE CASCADE,segment_id TEXT NOT NULL,source TEXT NOT NULL,translation TEXT NOT NULL,manual INTEGER NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS glossary_entries(book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,source TEXT NOT NULL,target TEXT NOT NULL,reading TEXT NOT NULL,PRIMARY KEY(book_id,source));
CREATE TABLE IF NOT EXISTS audio_assets(id TEXT PRIMARY KEY,cache_key TEXT NOT NULL,path TEXT NOT NULL,format TEXT NOT NULL,duration REAL NOT NULL,created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS assets_cache ON audio_assets(cache_key,created);
CREATE TABLE IF NOT EXISTS audio_clips(id TEXT PRIMARY KEY,segment_id TEXT NOT NULL REFERENCES segments(id) ON DELETE CASCADE,position INTEGER NOT NULL,text TEXT NOT NULL,asset_id TEXT REFERENCES audio_assets(id));
CREATE INDEX IF NOT EXISTS clips_segment ON audio_clips(segment_id,position);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,chapter_id TEXT NOT NULL REFERENCES chapters(id) ON DELETE CASCADE,kind TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL,done INTEGER NOT NULL,total INTEGER NOT NULL,message TEXT NOT NULL,created TEXT NOT NULL,cancel INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS jobs_status ON jobs(status,created);
CREATE TABLE IF NOT EXISTS job_items(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,position INTEGER NOT NULL,status TEXT NOT NULL,message TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS generation_attempts(id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES job_items(id) ON DELETE CASCADE,created TEXT NOT NULL,elapsed_ms INTEGER NOT NULL,usage TEXT,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS job_summaries(job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,position INTEGER NOT NULL,summary TEXT NOT NULL,PRIMARY KEY(job_id,position));
CREATE TABLE IF NOT EXISTS reading_progress(book_id TEXT PRIMARY KEY REFERENCES books(id) ON DELETE CASCADE,chapter_id TEXT NOT NULL,segment_id TEXT NOT NULL,clip_id TEXT NOT NULL,seconds REAL NOT NULL,revision INTEGER NOT NULL);
